<script setup lang="ts">defineProps<{loading?:boolean; error?:string; empty?:boolean; emptyText?:string}>();defineEmits<{retry:[]}>()</script>
<template><div v-if="error" class="error-state" role="alert"><strong>暂时未能加载</strong><p>{{ error }}</p><button class="button" @click="$emit('retry')">重新加载</button></div><div v-else-if="loading" class="skeleton-list" role="status" aria-label="正在加载"><div v-for="i in 4" :key="i" class="skeleton-row"><span></span><span></span><span></span></div><span class="sr-only">正在加载</span></div><div v-else-if="empty" class="empty-state"><strong>{{ emptyText || '暂无内容' }}</strong><slot name="empty" /></div><slot v-else /></template>
